@HiveType(typeId: 1)
class User extends HiveObject {
  @HiveField(0) String name;
  @HiveField(1) String email;
  @HiveField(2) DateTime createdAt;
  // ⚠️ Removed @HiveField(3) — never reuse number 3
  User({required this.name, required this.email, required this.createdAt});
}

// Bootstrap
Future<void> initStore() async {
  await Hive.initFlutter();
  Hive.registerAdapter(UserAdapter()); // from user.g.dart

  // Encryption — load (or create) the key from secure storage
  const secure = FlutterSecureStorage();
  var b64 = await secure.read(key: 'hive_key');
  if (b64 == null) {
    final key = Hive.generateSecureKey();
    await secure.write(key: 'hive_key', value: base64Encode(key));
    b64 = base64Encode(key);
  }
  final cipher = HiveAesCipher(base64Decode(b64));

  await Hive.openBox<User>('users', encryptionCipher: cipher);
}

